const input = $input.first();
const rawJson = (input && input.json) || {};

let triggerSource = 'internal';
let rawBody = {};

try {
  const trigWebhook = $('Webhook Trigger (jira-push-spec)').first();
  if (trigWebhook && trigWebhook.json) {
    triggerSource = 'webhook';
    rawBody = trigWebhook.json.body || trigWebhook.json;
  }
} catch (e) {}

if (triggerSource !== 'webhook') {
  try {
    const trigExec = $('Execute Workflow Trigger').first();
    if (trigExec && trigExec.json) {
      triggerSource = 'internal';
      rawBody = trigExec.json.body?.params || trigExec.json.body || trigExec.json.params || trigExec.json;
    }
  } catch (e) {}
}

const payload = Object.assign({}, rawJson, rawBody);
const rawKey = payload.issueKey || '';
const rawProject = (payload.project || '').trim();
const userName = payload.userName || 'User';
const isDryRun = Boolean(payload.dryRun);

const match = String(rawKey).match(/([A-Z][A-Z0-9]*-\d+)/i);
const issueKey = match ? match[1].toUpperCase() : '';

if (!issueKey) {
  const errMsg = `🚨 **[Lỗi Cú Pháp]** Không tìm thấy mã Jira \`issueKey\` hợp lệ trong lệnh.\n> Cú pháp: \`/agent [project] push-jira [issueKey]\`\n> Ví dụ: \`/agent 3.1 push-jira G3PTP-17396\``;
  return [{
    json: {
      isError: true,
      errorType: 'INVALID_ISSUE_KEY',
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

return [{
  json: {
    isError: false,
    issueKey: issueKey,
    project: rawProject,
    targetPath: 'spec',
    readContent: false,
    dryRun: isDryRun,
    userName: userName,
    _triggerSource: triggerSource
  }
}];

const fs = require('fs');
const path = require('path');

const input = $input.first();
const resolveRes = (input && input.json) || {};
const prepContext = $('Prepare Resolver Input').first()?.json || {};

const triggerSource = prepContext._triggerSource || resolveRes._triggerSource || 'internal';
const issueKey = prepContext.issueKey || resolveRes.issueKey || '';
const userName = prepContext.userName || resolveRes.userName || 'User';
const isDryRun = Boolean(prepContext.dryRun || resolveRes.dryRun);

// 1. Kiểm tra kết quả từ Workspace Resolver
if (resolveRes.isError || !resolveRes.found) {
  return [{
    json: {
      isError: true,
      errorType: resolveRes.errorType || 'DIR_NOT_FOUND',
      reportText: resolveRes.reportText || `🚨 Không tìm thấy thư mục workspace cho ticket **${issueKey}**.`,
      _triggerSource: triggerSource,
      userName,
      issueKey
    }
  }];
}

const specDir = resolveRes.resolvedPath || resolveRes.dirPath || '';
const refinedPath = path.join(specDir, 'refined.md');
const finalPath = path.join(specDir, 'final.md');

let targetFilePath = '';
let specType = '';

if (fs.existsSync(refinedPath)) {
  targetFilePath = refinedPath;
  specType = 'refined.md (chuẩn ba-refine)';
} else if (fs.existsSync(finalPath)) {
  targetFilePath = finalPath;
  specType = 'final.md (chuẩn ba-spec)';
} else {
  return [{
    json: {
      isError: true,
      errorType: 'SPEC_NOT_FOUND',
      reportText: `🚨 **[Không Tìm Thấy Spec]** Ticket **${issueKey}** chưa có file đặc tả chuẩn trong thư mục:\n> \`${specDir}\`\n\n*👉 Cần có ít nhất 1 trong 2 file: \`spec/refined.md\` (từ ba-refine) hoặc \`spec/final.md\` (từ ba-spec) trước khi đẩy lên Jira.*`,
      _triggerSource: triggerSource,
      userName,
      issueKey
    }
  }];
}

let markdownContent = '';
try {
  markdownContent = fs.readFileSync(targetFilePath, 'utf8');
} catch (e) {
  return [{
    json: {
      isError: true,
      errorType: 'READ_ERROR',
      reportText: `🚨 **[Lỗi Đọc File]** Không thể đọc nội dung file tại \`${targetFilePath}\`: ${e.message}`,
      _triggerSource: triggerSource,
      userName,
      issueKey
    }
  }];
}

if (!markdownContent.trim()) {
  return [{
    json: {
      isError: true,
      errorType: 'EMPTY_FILE',
      reportText: `🚨 **[File Spec Rỗng]** File tại \`${targetFilePath}\` không có nội dung.`,
      _triggerSource: triggerSource,
      userName,
      issueKey
    }
  }];
}

// 2. Pre-flight Quality Gate (Chuẩn ba-refine & ba-spec)
const qualityErrors = [];

// A. Chặn placeholder chưa điền
if (/\[\.\.\.\]/.test(markdownContent)) {
  qualityErrors.push("Spec còn chứa placeholder chưa điền: `[...]`");
}

// B. Chặn các section nội bộ bị cấm trên Jira
const forbiddenSections = [
  /##\s*Giả định\s*(&|và)\s*Rủi ro/i,
  /##\s*Ngoài Phạm vi/i,
  /##\s*Đánh giá Độ tin cậy/i,
  /##\s*(?:🧱\s*)?Technical Notes/i
];
for (const pattern of forbiddenSections) {
  if (pattern.test(markdownContent)) {
    qualityErrors.push(`Spec còn chứa section nội bộ bị cấm trên Jira: \`${pattern.source}\``);
  }
}

// C. Kiểm tra cấu trúc User Story (bắt buộc đối với refined.md)
if (targetFilePath.endsWith('refined.md')) {
  if (!/^##\s*(?:🧩\s*)?User Story/im.test(markdownContent)) {
    qualityErrors.push("Spec refine bắt buộc phải có `## 🧩 User Story` (`**As a**`, `**I want**`, `**So that**`).");
  }
}

// D. Kiểm tra cấu trúc Acceptance Criteria (Gherkin sạch, không @tag, không [AC-x.y])
const hasGiven = /Given\b/i.test(markdownContent);
const hasWhen = /When\b/i.test(markdownContent);
const hasThen = /Then\b/i.test(markdownContent);

if (!hasGiven || !hasWhen || !hasThen) {
  qualityErrors.push("Acceptance Criteria bắt buộc phải có cấu trúc Gherkin chuẩn (`Given` / `When` / `Then`).");
}

const scenarioCount = (markdownContent.match(/Scenario(?:\s+Outline)?\s*:/gi) || []).length;
if (scenarioCount < 2) {
  qualityErrors.push(`Acceptance Criteria cần có tối thiểu 2 Scenarios kiểm thử (hiện có: ${scenarioCount}).`);
}

// D.1. Chặn @tags thừa và [AC] trong Scenario
const lines = markdownContent.split('\n');
let inGherkin = false;
for (const line of lines) {
  if (/^```gherkin/i.test(line)) inGherkin = true;
  else if (/^```/.test(line)) inGherkin = false;
  else if (inGherkin) {
    if (/^\s*@[a-zA-Z0-9_-]+/.test(line)) {
      qualityErrors.push(`Acceptance Criteria không được chứa automation @tag: "${line.trim()}".`);
      break;
    }
    if (/Scenario(?:\s+Outline)?\s*:.*\[AC(?:-\d+(?:\.\d+)?)?\]/i.test(line)) {
      qualityErrors.push(`Scenario không được gắn tag mã [AC]: "${line.trim()}".`);
      break;
    }
  }
}

if (qualityErrors.length > 0) {
  const errMsg = `⚠️ **[Chặn Ghi Đè - Spec Chưa Đạt Chuẩn]** File \`${path.basename(targetFilePath)}\` của ticket **${issueKey}** chưa hoàn thiện:\n` +
                 qualityErrors.map(e => `> - ${e}`).join('\n') + '\n\n' +
                 `*Vui lòng mở file \`${targetFilePath}\` để hoàn thiện spec trước khi đẩy lên Jira.*`;
  return [{
    json: {
      isError: true,
      errorType: 'PREFLIGHT_FAILED',
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName,
      issueKey,
      filePath: targetFilePath
    }
  }];
}

// 3. Quét sơ đồ đính kèm trong diagrams/
let diagramFiles = [];
const diagramDir = path.join(specDir, 'diagrams');
if (fs.existsSync(diagramDir)) {
  try {
    diagramFiles = fs.readdirSync(diagramDir)
      .filter(f => f.endsWith('.png') || f.endsWith('.svg') || f.endsWith('.jpg'))
      .map(f => path.join(diagramDir, f));
  } catch (_) {}
}

// 4. Chuyển đổi Markdown sang ADF (Atlassian Document Format)
const projectRoot = ($env && $env.AGENT_WORKSPACE_DIR) || '/Users/qa-quangnt/Projects/agent-skills';
let adfContent = null;

try {
  const scriptPath = path.join(projectRoot, 'plugins/ba-po/skills/ba-refine/assets/jira-push-spec.js');
  if (fs.existsSync(scriptPath)) {
    const { markdownToAdf } = require(scriptPath);
    adfContent = markdownToAdf(markdownContent);
  }
} catch (e) {}

// Fallback nếu parser bị lỗi
if (!adfContent || !adfContent.content) {
  adfContent = {
    version: 1,
    type: 'doc',
    content: [
      {
        type: 'paragraph',
        content: [{ type: 'text', text: markdownContent }]
      }
    ]
  };
}

const tableCount = (adfContent.content || []).filter(n => n.type === 'table').length;
const blockCount = (adfContent.content || []).length;

const email = ($env && $env.ATLASSIAN_EMAIL) || '';
const token = ($env && $env.ATLASSIAN_API_TOKEN) || '';
const authHeader = 'Basic ' + Buffer.from(`${email}:${token}`).toString('base64');

return [{
  json: {
    isError: false,
    issueKey,
    project: resolveRes.project || prepContext.project,
    filePath: targetFilePath,
    specType,
    dryRun: isDryRun,
    adfContent,
    tableCount,
    blockCount,
    scenarioCount,
    diagramFiles,
    userName,
    authHeader,
    _triggerSource: triggerSource
  }
}];

const input = $input.first();
const json = (input && input.json) || {};

let specContext = {};
try {
  specContext = $('Pre-flight Gate & ADF Converter').first()?.json || {};
} catch (e) {}

const triggerSource = specContext._triggerSource || json._triggerSource || 'internal';
const issueKey = specContext.issueKey || json.issueKey || '';
const userName = specContext.userName || json.userName || 'User';
const baseUrl = (($env && $env.ATLASSIAN_BASE_URL) || 'https://entrade.atlassian.net').replace(/\/+$/, '');
const jiraUrl = `${baseUrl}/browse/${issueKey}`;

// 1. Trường hợp có lỗi từ bước Resolve hoặc Pre-flight
if (specContext.isError || json.isError) {
  return [{
    json: {
      success: false,
      isError: true,
      issueKey,
      reportText: specContext.reportText || json.reportText || 'Lỗi không xác định trong quá trình chuẩn bị spec.',
      _triggerSource: triggerSource,
      userName
    }
  }];
}

// 2. Trường hợp Dry Run
if (specContext.dryRun) {
  const dryRunMsg = `🧪 **[DRY RUN - Xem Trước Spec ADF]** Cho ticket [${issueKey}](${jiraUrl}):\n` +
                    `- **Nguồn file:** \`${specContext.filePath}\` (${specContext.specType || 'Spec'})\n` +
                    `- **Thống kê ADF:** ${specContext.blockCount || 0} blocks (gồm ${specContext.tableCount || 0} bảng nghiệp vụ, ${specContext.scenarioCount || 0} Scenarios AC)\n` +
                    `- **Sơ đồ phát hiện:** ${specContext.diagramFiles?.length || 0} sơ đồ diagrams\n` +
                    `> *Lưu ý: Chế độ Dry Run chỉ kiểm tra cú pháp và cấu trúc ADF, không ghi đè dữ liệu lên Jira.*`;
  return [{
    json: {
      success: true,
      isDryRun: true,
      issueKey,
      reportText: dryRunMsg,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

// 3. Trường hợp Live Push - kiểm tra phản hồi từ Jira API
if (json.error || json.errorMessages || (json.status && json.status >= 400)) {
  const errMsg = (json.errorMessages && json.errorMessages.join(', ')) ||
                 (json.error && (json.error.message || json.error.description)) ||
                 'Lỗi không xác định từ Jira REST API';
  const failText = `🚨 **[Lỗi Ghi Đè Jira]** Không thể cập nhật Description cho ticket [${issueKey}](${jiraUrl}):\n> ${errMsg}\n\n*Gợi ý: Kiểm tra quyền hạn của tài khoản hoặc cấu trúc ADF trong .env.*`;
  return [{
    json: {
      success: false,
      isError: true,
      issueKey,
      reportText: failText,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

const formattedUser = userName ? (userName.startsWith('@') ? userName : '@' + userName) : '@User';
const projectTag = specContext.project ? specContext.project + ' ' : '';

const successMsg = `### 🚀 Đẩy Đặc Tả Lên Jira Thành Công!
- **Ticket:** **[${issueKey}](${jiraUrl})**
- **Nguồn spec:** \`${specContext.filePath}\` (*${specContext.specType || 'Spec'}*)
- **Dự án/Cluster:** \`${specContext.project || 'Tự động phát hiện'}\`
- **Thống kê ADF:** **${specContext.blockCount || 0}** blocks (gồm **${specContext.tableCount || 0}** bảng nghiệp vụ, **${specContext.scenarioCount || 0}** Scenarios AC)
- **Sơ đồ liên quan:** ${specContext.diagramFiles?.length > 0 ? ('✅ ' + specContext.diagramFiles.length + ' file sơ đồ') : 'Không có sơ đồ riêng'}
- **Người thực hiện:** ${formattedUser}

---
💡 **Gợi ý bước tiếp theo theo quy trình BA/QA Pipeline:**
- \`/agent ${projectTag}push-squash ${issueKey}\` để đẩy kịch bản Gherkin (.feature) lên Squash TM
- \`/agent ${projectTag}run-test ${issueKey}\` để chạy kiểm thử tự động`;

return [{
  json: {
    success: true,
    isError: false,
    issueKey,
    jiraUrl,
    filePath: specContext.filePath,
    reportText: successMsg,
    _triggerSource: triggerSource,
    userName
  }
}];
